<script setup>
import {computed,onMounted,ref} from "vue";
import {confirmAction} from "../../services/alert.service.js";
import {createPlatformStaff,getPlatformAudit,getPlatformInvoices,getPlatformOrganizations,getPlatformOverview,getPlatformPayments,getPlatformStaff,getPlatformSubscriptions,platformLogin,platformLogout,resetPlatformStaffPassword,updateOrganizationAccess,updatePlatformStaff,updateSubscriptionControl} from "../../services/platform-admin.service.js";
const token=ref(localStorage.getItem("platform_staff_token")),me=ref(JSON.parse(localStorage.getItem("platform_staff")||"null"));const tab=ref("overview"),loading=ref(false),saving=ref(false);const overview=ref({summary:{},recent_groups:[],statuses:{}}),groups=ref([]),subscriptions=ref([]),payments=ref([]),invoices=ref([]),staff=ref([]),audit=ref([]);const credentials=ref({email:"",password:""}),showPassword=ref(false);const showStaff=ref(false),staffMode=ref("create"),editing=ref(null),staffForm=ref({name:"",email:"",password:"",role:"support",is_active:true});const showControl=ref(false),control=ref(null),reason=ref(""),subscriptionStatus=ref("active");
const isSuper=computed(()=>me.value?.role==="super_admin"),roles=["super_admin","operations","support","billing"];const roleName=v=>({super_admin:"Super Admin",operations:"Operations",support:"Support",billing:"Billing"}[v]||v);const money=v=>new Intl.NumberFormat("en-TZ",{style:"currency",currency:"TZS",maximumFractionDigits:0}).format(Number(v)||0);const date=v=>v?new Date(v).toLocaleString():"—";const title=v=>String(v||"").replaceAll("_"," ");const pageTitle=computed(()=>({overview:"Platform overview",groups:"VICOBA groups",subscriptions:"Subscriptions & trials",invoices:"Invoices",payments:"Payments",staff:"Platform staff",audit:"Admin activity"}[tab.value]));
const load=async()=>{if(!token.value)return;loading.value=true;try{const [o,g,s,i,p,st,a]=await Promise.all([getPlatformOverview(),getPlatformOrganizations(),getPlatformSubscriptions(),getPlatformInvoices(),getPlatformPayments(),getPlatformStaff(),getPlatformAudit()]);overview.value=o.data.data;groups.value=g.data.data;subscriptions.value=s.data.data;invoices.value=i.data.data;payments.value=p.data.data;staff.value=st.data.data;audit.value=a.data.data;}finally{loading.value=false;}};
const signIn=async()=>{saving.value=true;try{const r=await platformLogin(credentials.value);token.value=r.data.token;me.value=r.data.staff;localStorage.setItem("platform_staff_token",token.value);localStorage.setItem("platform_staff",JSON.stringify(me.value));await load();}finally{saving.value=false;}};const signOut=async()=>{try{await platformLogout();}finally{localStorage.removeItem("platform_staff_token");localStorage.removeItem("platform_staff");token.value=null;me.value=null;}};
const openStaffCreate=()=>{staffMode.value="create";editing.value=null;staffForm.value={name:"",email:"",password:"",role:"support",is_active:true};showStaff.value=true;};const openStaffEdit=item=>{staffMode.value="edit";editing.value=item;staffForm.value={name:item.name,email:item.email,password:"",role:item.role,is_active:item.is_active};showStaff.value=true;};const openPassword=item=>{staffMode.value="password";editing.value=item;staffForm.value={...staffForm.value,password:""};showStaff.value=true;};
const saveStaff=async()=>{saving.value=true;try{if(staffMode.value==="password"){const ok=await confirmAction({title:`Reset ${editing.value.name}'s password?`,text:"All existing sessions will end.",confirmText:"Reset password",danger:true});if(!ok)return;await resetPlatformStaffPassword(editing.value.id,staffForm.value.password);}else if(editing.value)await updatePlatformStaff(editing.value.id,{name:staffForm.value.name,role:staffForm.value.role,is_active:staffForm.value.is_active});else await createPlatformStaff(staffForm.value);showStaff.value=false;await load();}finally{saving.value=false;}};
const openGroupControl=item=>{control.value={kind:"group",item};reason.value="";showControl.value=true;};const openSubscriptionControl=item=>{control.value={kind:"subscription",item};subscriptionStatus.value=item.status==="suspended"?"active":"suspended";reason.value="";showControl.value=true;};const saveControl=async()=>{saving.value=true;try{if(control.value.kind==="group")await updateOrganizationAccess(control.value.item.id,{is_active:!control.value.item.is_active,reason:reason.value});else await updateSubscriptionControl(control.value.item.organization_id,{status:subscriptionStatus.value,reason:reason.value});showControl.value=false;await load();}finally{saving.value=false;}};
onMounted(load);window.addEventListener("platform-session-expired",()=>{token.value=null;me.value=null;});
</script>
<template><main v-if="!token" class="login"><section><a href="/" class="brand"><b>V</b><span><strong>Vikoba Control</strong><small>Platform administration</small></span></a><div class="login-copy"><small>RESTRICTED AREA</small><h1>Super Admin control center</h1><p>Monitor every group, subscription, payment, and authorized platform operator.</p></div><form @submit.prevent="signIn"><label>Email<input v-model.trim="credentials.email" type="email" required autocomplete="username"></label><label>Password<div><input v-model="credentials.password" :type="showPassword?'text':'password'" required autocomplete="current-password"><button type="button" @click="showPassword=!showPassword"><i class="bi" :class="showPassword?'bi-eye-slash':'bi-eye'"></i></button></div></label><button class="primary" :disabled="saving">{{saving?'Signing in...':'Open control center'}}</button></form><a href="/" class="back">← Return to website</a></section><aside><i class="bi bi-shield-lock"></i><h2>One secure view of the entire Vikoba platform.</h2><p>Tenant data remains isolated while authorized platform staff access operational and billing metadata.</p></aside></main>
<div v-else class="shell"><aside class="rail"><div class="brand"><b>V</b><span><strong>Vikoba</strong><small>Control center</small></span></div><nav><button v-for="item in [{id:'overview',icon:'bi-grid',label:'Overview'},{id:'groups',icon:'bi-buildings',label:'Groups'},{id:'subscriptions',icon:'bi-credit-card',label:'Subscriptions'},{id:'invoices',icon:'bi-receipt',label:'Invoices'},{id:'payments',icon:'bi-cash-stack',label:'Payments'},{id:'staff',icon:'bi-people',label:'Staff'},{id:'audit',icon:'bi-clock-history',label:'Activity'}]" :key="item.id" :class="{active:tab===item.id}" @click="tab=item.id"><i class="bi" :class="item.icon"></i>{{item.label}}</button><a href="/dashboard"><i class="bi bi-box-arrow-up-right"></i>Group app</a></nav><div class="account"><strong>{{me.name}}</strong><small>{{roleName(me.role)}}</small><button @click="signOut"><i class="bi bi-box-arrow-right"></i>Sign out</button></div></aside><section class="workspace"><header><div><small>PLATFORM ADMINISTRATION</small><h1>{{pageTitle}}</h1></div><button v-if="tab==='staff'&&isSuper" class="primary" @click="openStaffCreate"><i class="bi bi-plus-lg"></i>Add staff</button></header><div class="mobile-nav"><button v-for="id in ['overview','groups','subscriptions','invoices','payments','staff','audit']" :key="id" :class="{active:tab===id}" @click="tab=id">{{title(id)}}</button></div><div v-if="loading" class="state"><span class="spinner-border spinner-border-sm"></span>Loading platform data...</div>
<main v-else class="content"><template v-if="tab==='overview'"><section class="metrics wide"><article><span>Total groups</span><strong>{{overview.summary.groups||0}}</strong><small>{{overview.summary.active_groups||0}} active</small></article><article><span>Members managed</span><strong>{{overview.summary.members||0}}</strong><small>Across all groups</small></article><article><span>Active subscriptions</span><strong>{{overview.summary.active_subscriptions||0}}</strong><small>{{overview.summary.trialing||0}} on trial</small></article><article><span>Verified revenue</span><strong>{{money(overview.summary.paid_revenue)}}</strong><small>Paid subscriptions</small></article></section><section class="overview-grid"><div class="panel"><div class="panel-title"><div><h2>Recently registered groups</h2><p>Newest tenant workspaces.</p></div><button @click="tab='groups'">View all</button></div><div class="cards"><article v-for="group in overview.recent_groups" :key="group.id"><span class="group-mark">{{group.name[0]}}</span><div><strong>{{group.name}}</strong><small>{{group.billing_email}} · {{group.member_count}} members</small></div><b class="status" :class="group.subscription?.status">{{title(group.subscription?.status||'none')}}</b></article></div></div><div class="panel status-panel"><div class="panel-title"><div><h2>Subscription health</h2><p>Current portfolio status.</p></div></div><div v-for="(count,status) in overview.statuses" :key="status" class="status-row"><span>{{title(status)}}</span><strong>{{count}}</strong></div></div></section></template>
<section v-else-if="tab==='groups'" class="panel"><div class="panel-title"><div><h2>All VICOBA groups</h2><p>Workspace access, owner contacts, members, and subscription position.</p></div><span>{{groups.length}} groups</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Group</th><th>Members</th><th>Plan</th><th>Subscription</th><th>Created</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="g in groups" :key="g.id"><td><strong>{{g.name}}</strong><small>{{g.billing_email}} · {{g.billing_phone||'No phone'}}</small></td><td>{{g.member_count}} <small>{{g.user_count}} users</small></td><td>{{g.subscription?.plan_name||'No plan'}}</td><td><b class="status" :class="g.subscription?.status">{{title(g.subscription?.status||'none')}}</b></td><td>{{date(g.created_at)}}</td><td><b class="status" :class="{off:!g.is_active}">{{g.is_active?'Active':'Suspended'}}</b></td><td><button v-if="isSuper" class="icon-button" @click="openGroupControl(g)"><i class="bi" :class="g.is_active?'bi-slash-circle':'bi-check-circle'"></i></button></td></tr></tbody></table></div></section>
<section v-else-if="tab==='subscriptions'" class="panel"><div class="panel-title"><div><h2>Subscriptions and free trials</h2><p>Plan, renewal, trial, invoice, and payment position for every group.</p></div></div><div class="table-responsive"><table class="table"><thead><tr><th>Group</th><th>Plan</th><th>Status</th><th>Trial ends</th><th>Period ends</th><th>Invoices</th><th>Paid</th><th></th></tr></thead><tbody><tr v-for="s in subscriptions" :key="s.organization_id"><td><strong>{{s.organization_name}}</strong><small>{{s.billing_email}}</small></td><td>{{s.plan_name||'Not assigned'}}<small v-if="s.price_tzs">{{money(s.price_tzs)}} / {{s.billing_interval}}</small></td><td><b class="status" :class="s.status">{{title(s.status||'none')}}</b></td><td>{{date(s.trial_ends_at)}}</td><td>{{date(s.current_period_ends_at)}}</td><td>{{s.invoice_summary.count}}<small>{{money(s.invoice_summary.pending_total)}} pending</small></td><td>{{money(s.payment_summary.paid_total)}}</td><td><button v-if="isSuper&&s.id" class="icon-button" @click="openSubscriptionControl(s)"><i class="bi bi-sliders"></i></button></td></tr></tbody></table></div></section>
<section v-else-if="tab==='invoices'" class="panel"><div class="panel-title"><div><h2>Subscription invoices</h2><p>All issued, paid, pending, failed, and refunded invoices.</p></div><span>{{invoices.length}} invoices</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Invoice</th><th>Group</th><th>Plan</th><th>Status</th><th>Amount</th><th>Due</th><th>Paid</th><th>Created</th></tr></thead><tbody><tr v-for="i in invoices" :key="i.id"><td><code>{{i.invoice_number}}</code></td><td>{{i.organization_name}}</td><td>{{i.plan_name}}</td><td><b class="status" :class="i.status">{{title(i.status)}}</b></td><td><strong>{{money(i.amount_tzs)}}</strong></td><td>{{date(i.due_at)}}</td><td>{{date(i.paid_at)}}</td><td>{{date(i.created_at)}}</td></tr><tr v-if="!invoices.length"><td colspan="8" class="empty">No invoices issued yet.</td></tr></tbody></table></div></section><section v-else-if="tab==='payments'" class="panel"><div class="panel-title"><div><h2>Subscription payments</h2><p>Provider references and verified payment states.</p></div><span>{{money(payments.filter(p=>p.status==='paid').reduce((n,p)=>n+Number(p.amount_tzs),0))}} paid</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Reference</th><th>Group</th><th>Invoice</th><th>Provider</th><th>Method</th><th>Status</th><th>Amount</th><th>Date</th></tr></thead><tbody><tr v-for="p in payments" :key="p.id"><td><code>{{p.reference}}</code></td><td>{{p.organization_name}}</td><td>{{p.invoice_number}}</td><td>{{p.provider}}</td><td>{{title(p.payment_method||'not supplied')}}</td><td><b class="status" :class="p.status">{{title(p.status)}}</b></td><td><strong>{{money(p.amount_tzs)}}</strong></td><td>{{date(p.paid_at||p.created_at)}}</td></tr><tr v-if="!payments.length"><td colspan="8" class="empty">No subscription payments yet.</td></tr></tbody></table></div></section>
<section v-else-if="tab==='staff'" class="panel"><div class="panel-title"><div><h2>Platform staff</h2><p>People authorized to operate the Vikoba service.</p></div><span>{{staff.filter(x=>x.is_active).length}} active</span></div><div class="table-responsive"><table class="table"><thead><tr><th>Staff</th><th>Role</th><th>Status</th><th>Last sign-in</th><th></th></tr></thead><tbody><tr v-for="item in staff" :key="item.id"><td><strong>{{item.name}}</strong><small>{{item.email}}</small></td><td>{{roleName(item.role)}}</td><td><b class="status" :class="{off:!item.is_active}">{{item.is_active?'Active':'Deactivated'}}</b></td><td>{{date(item.last_login_at)}}</td><td><div v-if="isSuper" class="actions"><button @click="openStaffEdit(item)"><i class="bi bi-pencil"></i></button><button @click="openPassword(item)"><i class="bi bi-key"></i></button></div></td></tr></tbody></table></div></section>
<section v-else class="panel"><div class="panel-title"><div><h2>Administrative activity</h2><p>Security-sensitive platform actions.</p></div></div><div class="audit"><article v-for="event in audit" :key="event.id"><i class="bi bi-shield-check"></i><div><strong>{{title(event.action)}}</strong><span>{{event.actor_name||'System'}} · {{event.details?.reason||event.target_name||'Administrative action'}}</span></div><time>{{date(event.created_at)}}</time></article></div></section></main></section>
<div v-if="showStaff" class="modal-backdrop"><div class="modal-panel"><div class="modal-panel-header"><div><small>STAFF ACCESS</small><h5>{{staffMode==='password'?'Reset password':editing?'Edit staff':'Add platform staff'}}</h5></div><button class="btn-close" @click="showStaff=false"></button></div><form @submit.prevent="saveStaff"><template v-if="staffMode!=='password'"><label>Full name<input v-model.trim="staffForm.name" class="form-control" required></label><label>Email<input v-model.trim="staffForm.email" class="form-control" type="email" :disabled="editing" required></label><label>Role<select v-model="staffForm.role" class="form-select"><option v-for="r in roles" :key="r" :value="r">{{roleName(r)}}</option></select></label><label v-if="!editing">Temporary password<input v-model="staffForm.password" class="form-control" type="password" minlength="8" required></label><label v-else class="check"><input v-model="staffForm.is_active" type="checkbox">Account active</label></template><label v-else>Temporary password<input v-model="staffForm.password" class="form-control" type="password" minlength="8" required></label><div class="modal-actions"><button type="button" class="btn btn-outline-secondary" @click="showStaff=false">Cancel</button><button class="btn btn-primary" :disabled="saving">{{saving?'Saving...':'Save'}}</button></div></form></div></div>
<div v-if="showControl" class="modal-backdrop"><div class="modal-panel confirm-panel"><div class="modal-panel-header"><div><small>SECURITY CONTROL</small><h5>{{control.kind==='group'?(control.item.is_active?'Suspend group':'Reactivate group'):'Change subscription status'}}</h5></div><button class="btn-close" @click="showControl=false"></button></div><form @submit.prevent="saveControl"><p>This action is recorded permanently in the platform audit trail.</p><label v-if="control.kind==='subscription'">New status<select v-model="subscriptionStatus" class="form-select"><option value="active">Active</option><option value="suspended">Suspended</option><option value="cancelled">Cancelled</option><option value="expired">Expired</option></select></label><label>Reason<textarea v-model.trim="reason" class="form-control" minlength="5" rows="3" required></textarea></label><div class="modal-actions"><button type="button" class="btn btn-outline-secondary" @click="showControl=false">Cancel</button><button class="btn btn-danger" :disabled="saving">{{saving?'Applying...':'Confirm change'}}</button></div></form></div></div></div></template>
<style scoped>*{box-sizing:border-box}.login{min-height:100dvh;display:grid;background:#f7f7f9;color:#29262e}.login>section{display:flex;flex-direction:column;padding:1.5rem;background:#fff}.brand{display:flex;align-items:center;gap:.65rem;color:inherit;text-decoration:none}.brand b{width:2.2rem;height:2.2rem;display:grid;place-items:center;border-radius:8px;background:#7256df;color:#fff}.brand strong,.brand small,.login label,.account strong,.account small,td strong,td small{display:block}.brand small,.account small,td small{color:#8b8790;font-size:.61rem}.login-copy{margin:auto 0 1.5rem;padding-top:3rem}.login-copy small,.workspace>header small,.modal-panel-header small{color:#7256df;font-size:.6rem;font-weight:800;letter-spacing:.08em}.login-copy h1{margin:.5rem 0;font-size:clamp(2rem,8vw,3rem);letter-spacing:-.05em}.login-copy p{max-width:430px;color:#817d86;font-size:.75rem}.login form,.modal-panel form{display:grid;gap:1rem}.login label,.modal-panel form>label{color:#5f5b64;font-size:.69rem;font-weight:700}.login input{width:100%;min-height:48px;padding:.7rem;border:1px solid #ddd9e1;border-radius:8px}.login label>div{display:flex;border:1px solid #ddd9e1;border-radius:8px}.login label>div input{border:0}.login label button{border:0;background:transparent}.primary{min-height:40px;padding:.6rem .9rem;border:0;border-radius:8px;background:#7256df;color:#fff;font-size:.7rem;font-weight:700}.back{margin-top:1rem;color:#7256df;text-decoration:none;font-size:.67rem}.login aside{display:none}.shell{min-height:100dvh;background:#f6f7f9;color:#29262e}.rail{position:fixed;inset:0 auto 0 0;width:220px;display:none;flex-direction:column;padding:1.2rem;border-right:1px solid #e8e7eb;background:#fff}.rail nav{display:grid;gap:.25rem;margin-top:2rem}.rail nav button,.rail nav a{display:flex;align-items:center;gap:.65rem;padding:.65rem;border:0;border-radius:7px;background:transparent;color:#6e6a73;text-decoration:none;font-size:.7rem}.rail nav .active{background:#eeeaff;color:#6548cf;font-weight:700}.account{margin-top:auto;border-top:1px solid #eee;padding-top:1rem}.account button{margin-top:.7rem;border:0;background:transparent;color:#b34854;font-size:.67rem}.workspace>header{position:sticky;top:0;z-index:4;display:flex;align-items:center;justify-content:space-between;padding:1rem;border-bottom:1px solid #e8e7eb;background:rgba(255,255,255,.97)}.workspace h1{margin:.15rem 0 0;font-size:1.1rem}.mobile-nav{display:flex;gap:.3rem;overflow:auto;padding:.6rem;background:#fff}.mobile-nav button{white-space:nowrap;border:0;border-radius:7px;padding:.5rem;background:#f3f1f6;color:#69646e;font-size:.64rem}.mobile-nav .active{background:#7256df;color:#fff}.content{padding:1rem}.state{min-height:45vh;display:flex;align-items:center;justify-content:center;gap:.5rem;color:#7e7983}.metrics{display:grid;gap:.65rem;margin-bottom:1rem}.metrics article{padding:1rem;border:1px solid #e7e5ea;border-radius:11px;background:#fff}.metrics span,.metrics strong,.metrics small{display:block}.metrics span{color:#87838c;font-size:.62rem}.metrics strong{margin:.3rem 0;font-size:1.15rem}.metrics small{color:#99959e;font-size:.6rem}.overview-grid{display:grid;gap:1rem}.panel{border:1px solid #e7e5ea;border-radius:12px;background:#fff;overflow:hidden}.panel-title{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:1rem}.panel-title h2{margin:0;font-size:.87rem}.panel-title p{margin:.15rem 0 0;color:#8a8690;font-size:.64rem}.panel-title>span,.panel-title button{border:0;border-radius:99px;padding:.3rem .55rem;background:#eeeaff;color:#6548cf;font-size:.61rem}.cards article{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:.65rem;padding:.75rem 1rem;border-top:1px solid #efedf1}.group-mark{width:2rem;height:2rem;display:grid;place-items:center;border-radius:8px;background:#eeeaff;color:#6548cf;font-weight:800}.cards strong,.cards small{display:block}.cards strong{font-size:.7rem}.cards small{color:#8b8790;font-size:.6rem}.status-row{display:flex;justify-content:space-between;padding:.7rem 1rem;border-top:1px solid #eee;font-size:.68rem;text-transform:capitalize}.table{min-width:900px;margin:0;font-size:.68rem}.table th{color:#8c8891;font-size:.6rem;font-weight:600}.table td{vertical-align:middle}.status{display:inline-flex;padding:.27rem .5rem;border-radius:99px;background:#eef0f3;color:#6c6870;font-size:.59rem;text-transform:capitalize}.status.active,.status.paid{background:#e9f8ef;color:#168657}.status.trialing,.status.pending,.status.processing{background:#fff5dd;color:#956006}.status.expired,.status.cancelled,.status.suspended,.status.failed,.status.off{background:#fff0f1;color:#c54b58}.icon-button,.actions button{width:1.9rem;height:1.9rem;border:1px solid #e5e2e9;border-radius:6px;background:#fff;color:#625d68}.actions{display:flex;gap:.3rem}.audit article{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:.7rem;padding:.8rem 1rem;border-top:1px solid #eee}.audit article>i{width:2rem;height:2rem;display:grid;place-items:center;border-radius:8px;background:#eeeaff;color:#6548cf}.audit strong,.audit span{display:block;font-size:.68rem}.audit span,.audit time{color:#8b8790;font-size:.6rem}.empty{text-align:center;color:#8b8790}.modal-panel form{padding-top:1rem}.check{display:flex!important;align-items:center;gap:.5rem}.confirm-panel p{padding:.7rem;border-radius:8px;background:#fff5dd;color:#806018;font-size:.67rem}@media(min-width:600px){.metrics{grid-template-columns:repeat(2,1fr)}}@media(min-width:800px){.login{grid-template-columns:minmax(400px,.8fr) minmax(460px,1.2fr)}.login>section{padding:clamp(2rem,6vw,5rem)}.login aside{display:flex;flex-direction:column;justify-content:center;padding:clamp(3rem,8vw,8rem);background:linear-gradient(145deg,#292231,#513a91);color:#fff}.login aside h2{font-size:clamp(2.5rem,5vw,4rem);letter-spacing:-.05em}.login aside p{color:#d5cfe2}.rail{display:flex}.workspace{margin-left:220px}.mobile-nav{display:none}.workspace>header,.content{padding:1.25rem 1.5rem}.metrics.wide{grid-template-columns:repeat(4,1fr)}.overview-grid{grid-template-columns:minmax(0,1.6fr) minmax(250px,.6fr)}}
</style>
